import { DatabaseSync } from "node:sqlite";
import { LATEST_VERSION, migrate } from "@driftnet/core/migrations";
import { reindexAll } from "@driftnet/core/search-index";

const SNAPSHOT_VERSION = 1 as const;
const BEGIN = "<!-- DRIFTNET_STATE_BEGIN -->";
const END = "<!-- DRIFTNET_STATE_END -->";

/**
 * Tables that contain canonical Driftnet state. item_fts and item_vec are derived
 * indexes and intentionally stay out of Git: FTS is rebuilt on hydrate and
 * embeddings can be regenerated by the semantic-search worker.
 */
const TABLES = [
  "folders",
  "items",
  "aliases",
  "shares",
  "feedback",
  "state",
  "found_in",
  "notes",
  "agent_tokens",
  "pair_codes",
  "item_history",
] as const;

type TableName = (typeof TABLES)[number];
type Cell = string | number | null;
type Row = Record<string, Cell>;

interface Snapshot {
  driftnetSnapshot: typeof SNAPSHOT_VERSION;
  schema: number;
  updatedAt: string;
  tables: Record<TableName, Row[]>;
}

interface DataConfig {
  token: string;
  repo: string;
  branch: string;
  path: string;
}

interface RemoteFile {
  sha: string;
  text: string;
}

interface GitHubContentResponse {
  type?: string;
  sha?: string;
  content?: string;
  encoding?: string;
}

interface GitHubWriteResponse {
  content?: { sha?: string } | null;
}

export interface HydrateResult {
  sourceSha: string | null;
  found: boolean;
}

function config(env: NodeJS.ProcessEnv): DataConfig {
  const token = env.DRIFTNET_GITHUB_TOKEN?.trim();
  const repo = env.DRIFTNET_DATA_REPO?.trim();
  if (!token) throw new Error("DRIFTNET_GITHUB_TOKEN is required on Vercel");
  if (!repo || !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo)) {
    throw new Error("DRIFTNET_DATA_REPO must be owner/repo, for example ger0182/driftnet-data");
  }
  return {
    token,
    repo,
    branch: env.DRIFTNET_DATA_BRANCH?.trim() || "main",
    path: env.DRIFTNET_DATA_PATH?.trim().replace(/^\/+/, "") || "data/driftnet-state.md",
  };
}

function headers(token: string): Record<string, string> {
  return {
    accept: "application/vnd.github+json",
    authorization: `Bearer ${token}`,
    "content-type": "application/json",
    "user-agent": "driftnet-vercel",
    "x-github-api-version": "2022-11-28",
  };
}

function contentUrl(c: DataConfig): string {
  const path = c.path.split("/").map(encodeURIComponent).join("/");
  return `https://api.github.com/repos/${c.repo}/contents/${path}?ref=${encodeURIComponent(c.branch)}`;
}

function writeUrl(c: DataConfig): string {
  const path = c.path.split("/").map(encodeURIComponent).join("/");
  return `https://api.github.com/repos/${c.repo}/contents/${path}`;
}

async function errorText(res: Response): Promise<string> {
  try {
    const body = await res.json() as { message?: string };
    return body.message || res.statusText;
  } catch {
    return res.statusText;
  }
}

/** Refuse an accidentally-public data repository unless the owner explicitly opts in. */
export async function assertPrivateDataRepo(env: NodeJS.ProcessEnv): Promise<void> {
  const c = config(env);
  const res = await fetch(`https://api.github.com/repos/${c.repo}`, { headers: headers(c.token) });
  if (!res.ok) throw new Error(`cannot inspect GitHub data repo ${c.repo}: ${res.status} ${await errorText(res)}`);
  const repo = await res.json() as { private?: boolean };
  if (repo.private !== true && env.DRIFTNET_ALLOW_PUBLIC_DATA_REPO !== "1") {
    throw new Error(`${c.repo} is public. Driftnet data may contain private notes and token hashes; use a private repo or explicitly set DRIFTNET_ALLOW_PUBLIC_DATA_REPO=1.`);
  }
}

async function fetchRemoteFile(env: NodeJS.ProcessEnv): Promise<RemoteFile | null> {
  const c = config(env);
  const res = await fetch(contentUrl(c), { headers: headers(c.token), cache: "no-store" });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`cannot read ${c.repo}/${c.path}: ${res.status} ${await errorText(res)}`);
  const body = await res.json() as GitHubContentResponse;
  if (body.type !== "file" || !body.sha || body.encoding !== "base64" || typeof body.content !== "string") {
    throw new Error(`unexpected GitHub Contents response for ${c.repo}/${c.path}`);
  }
  return {
    sha: body.sha,
    text: Buffer.from(body.content.replace(/\s/g, ""), "base64").toString("utf8"),
  };
}

export async function remoteDataSha(env: NodeJS.ProcessEnv): Promise<string | null> {
  return (await fetchRemoteFile(env))?.sha ?? null;
}

function parseMarkdown(text: string): Snapshot {
  const start = text.indexOf(BEGIN);
  const end = text.indexOf(END, start + BEGIN.length);
  if (start < 0 || end < 0 || end <= start) throw new Error("Driftnet data Markdown is missing snapshot markers");
  const raw = text.slice(start + BEGIN.length, end).trim();
  const parsed = JSON.parse(raw) as Partial<Snapshot>;
  if (parsed.driftnetSnapshot !== SNAPSHOT_VERSION || typeof parsed.schema !== "number" || !parsed.tables || typeof parsed.tables !== "object") {
    throw new Error("unsupported or invalid Driftnet Markdown snapshot");
  }
  if (parsed.schema > LATEST_VERSION) {
    throw new Error(`data snapshot schema ${parsed.schema} is newer than this Driftnet build (schema ${LATEST_VERSION})`);
  }
  for (const table of TABLES) {
    if (!Array.isArray((parsed.tables as Partial<Record<TableName, unknown>>)[table])) {
      throw new Error(`data snapshot is missing table ${table}`);
    }
  }
  return parsed as Snapshot;
}

function toMarkdown(snapshot: Snapshot): string {
  return [
    "# Driftnet data snapshot",
    "",
    "> Managed automatically by the Driftnet Vercel adapter. Keep this repository private.",
    "> The JSON block below is the canonical persisted state; SQLite on Vercel is only a temporary runtime index.",
    "",
    BEGIN,
    JSON.stringify(snapshot, null, 2),
    END,
    "",
  ].join("\n");
}

function columnsOf(db: DatabaseSync, table: TableName): Set<string> {
  return new Set((db.prepare(`PRAGMA table_info(${table})`).all() as { name: string }[]).map((r) => r.name));
}

function restore(db: DatabaseSync, snapshot: Snapshot): void {
  db.exec("BEGIN");
  try {
    // Remove children before parents. SQLite's foreign-key enforcement is off in
    // the current Store, but this order is safe if it is enabled in the future.
    for (const table of [...TABLES].reverse()) db.exec(`DELETE FROM ${table}`);

    for (const table of TABLES) {
      const allowed = columnsOf(db, table);
      for (const row of snapshot.tables[table] ?? []) {
        const cols = Object.keys(row).filter((name) => allowed.has(name));
        if (!cols.length) continue;
        const placeholders = cols.map(() => "?").join(", ");
        db.prepare(`INSERT INTO ${table} (${cols.join(", ")}) VALUES (${placeholders})`)
          .run(...cols.map((name) => row[name] ?? null));
      }
    }
    reindexAll(db);
    db.exec("COMMIT");
  } catch (err) {
    try { db.exec("ROLLBACK"); } catch { /* already rolled back */ }
    throw err;
  }
}

function takeSnapshot(db: DatabaseSync): Snapshot {
  const tables = {} as Record<TableName, Row[]>;
  for (const table of TABLES) tables[table] = db.prepare(`SELECT * FROM ${table}`).all() as Row[];
  const schema = (db.prepare("PRAGMA user_version").get() as { user_version: number }).user_version;
  return {
    driftnetSnapshot: SNAPSHOT_VERSION,
    schema,
    updatedAt: new Date().toISOString(),
    tables,
  };
}

/** Build the temporary SQLite index from the canonical Markdown file. */
export async function hydrateFromGithub(dbPath: string, env: NodeJS.ProcessEnv): Promise<HydrateResult> {
  const db = new DatabaseSync(dbPath);
  try {
    migrate(db, { path: dbPath });
    const remote = await fetchRemoteFile(env);
    if (!remote) return { sourceSha: null, found: false };
    restore(db, parseMarkdown(remote.text));
    return { sourceSha: remote.sha, found: true };
  } finally {
    db.close();
  }
}

/**
 * Persist the whole logical catalogue as Markdown. expectedSha is the version
 * this runtime hydrated from, so GitHub rejects a concurrent overwrite instead
 * of silently losing another Vercel instance's write.
 */
export async function persistToGithub(dbPath: string, env: NodeJS.ProcessEnv, expectedSha: string | null): Promise<string> {
  const c = config(env);
  const db = new DatabaseSync(dbPath);
  let snapshot: Snapshot;
  try {
    snapshot = takeSnapshot(db);
  } finally {
    db.close();
  }

  const body: Record<string, unknown> = {
    message: `data: persist Driftnet ${snapshot.updatedAt}`,
    content: Buffer.from(toMarkdown(snapshot), "utf8").toString("base64"),
    branch: c.branch,
  };
  if (expectedSha) body.sha = expectedSha;

  const res = await fetch(writeUrl(c), {
    method: "PUT",
    headers: headers(c.token),
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const hint = res.status === 409 || res.status === 422
      ? " (the GitHub copy changed concurrently; retry the write from a fresh request)"
      : "";
    throw new Error(`cannot persist ${c.repo}/${c.path}: ${res.status} ${await errorText(res)}${hint}`);
  }
  const written = await res.json() as GitHubWriteResponse;
  const sha = written.content?.sha;
  if (!sha) throw new Error("GitHub accepted the data commit but did not return the new content SHA");
  return sha;
}
